syntax:
const unsigned int MAGIC_NUMBER = 0xXXXXXX; // Embedded at a specific offset in data structures or files
// Usage in code:
if (data->magic == MAGIC_NUMBER) { /* proceed with processing */ }

code_example:
#define FS_MAGIC 0x011954
struct superblock {
    unsigned int magic; // Magic number to identify filesystem superblock
    // other fields
};
struct superblock sb;
if (sb.magic == FS_MAGIC) {
    // Confirmed valid superblock, proceed with filesystem operations
}
